const b = $input.first().json.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
if (!UUID.test(String(b.id || ''))) return [{ json: { ok: false } }];
// Solo los campos permitidos, saneados (igual que main/stats.js)
const rec = {
  id: String(b.id),
  version: String(b.version || '').slice(0, 32),
  lang: /^[a-z]{2,3}(-[A-Za-z]{2,4})?$/.test(String(b.lang || '')) ? String(b.lang) : 'und',
  os: ['Windows 10', 'Windows 11'].includes(b.os) ? b.os : 'otro',
  decks: Number(b.decks) === 4 ? 4 : 2,
  controller: b.controller === true,
  fecha: DateTime.now().setZone('Europe/Madrid').toISO()
};
const day = DateTime.now().setZone('Europe/Madrid').toISODate();
const data = $getWorkflowStaticData('global');
data.days = data.days || {};
(data.days[day] = data.days[day] || {})[rec.id] = rec;
// limpieza: registros de más de 90 días
const limit = DateTime.now().setZone('Europe/Madrid').minus({ days: 90 }).toISODate();
for (const d of Object.keys(data.days)) if (d < limit) delete data.days[d];
return [{ json: { ok: true } }];

const tz = 'Europe/Madrid';
const data = $getWorkflowStaticData('global');
data.days = data.days || {};
data.summaries = data.summaries || {};
const yday = DateTime.now().setZone(tz).minus({ days: 1 }).toISODate();
const recs = Object.values(data.days[yday] || {});
const count = (key) => recs.reduce((m, r) => { const k = String(r[key]); m[k] = (m[k] || 0) + 1; return m; }, {});
const uniq = (n) => { const s = new Set(); for (let i = 0; i < n; i++) { const d = DateTime.now().setZone(tz).minus({ days: 1 + i }).toISODate(); Object.keys(data.days[d] || {}).forEach(id => s.add(id)); } return s.size; };
const summary = {
  fecha: yday,
  activas: recs.length,
  activas7dias: uniq(7),
  activas30dias: uniq(30),
  versiones: count('version'),
  sistemas: count('os'),
  idiomas: count('lang'),
  decks: count('decks'),
  conControladora: recs.filter(r => r.controller).length
};
data.summaries[yday] = summary;
const limit = DateTime.now().setZone(tz).minus({ days: 730 }).toISODate();
for (const d of Object.keys(data.summaries)) if (d < limit) delete data.summaries[d];
const list = (o) => Object.entries(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}: ${v}`).join(' · ') || '—';
const text = [
  `Instalaciones activas el ${yday}: ${summary.activas}`,
  `Últimos 7 días: ${summary.activas7dias} · últimos 30 días: ${summary.activas30dias}`,
  `Versiones: ${list(summary.versiones)}`,
  `Windows: ${list(summary.sistemas)}`,
  `Idiomas: ${list(summary.idiomas)}`,
  `Decks: ${list(summary.decks)}`,
  `Con controladora MIDI: ${summary.conControladora} de ${summary.activas}`
].join('\n');
return [{ json: { ...summary, text } }];
